-- Archer: public-website content tables (phpMyAdmin / MySQL 5.7+ / MariaDB 10.2+)
-- Mirrors migration 2026_11_14_000001_create_site_content_tables and SiteContentSeeder.
-- Safe to re-run: tables use IF NOT EXISTS and seed rows use ON DUPLICATE KEY UPDATE.
-- Rates are the figures shown on the current website; confirm against the approved rules package.

SET NAMES utf8mb4;
START TRANSACTION;

CREATE TABLE IF NOT EXISTS `site_tiers` (
  `id` char(36) NOT NULL,
  `kind` varchar(20) NOT NULL,
  `tier` tinyint unsigned NOT NULL,
  `label` varchar(255) NOT NULL,
  `title` varchar(255) NOT NULL,
  `call_only` tinyint(1) NOT NULL DEFAULT 0,
  `credentials` json NOT NULL,
  `suited_for` json NOT NULL,
  `sort_order` int unsigned NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `site_tiers_kind_tier_unique` (`kind`,`tier`),
  KEY `site_tiers_is_active_index` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `site_vehicles` (
  `id` char(36) NOT NULL,
  `vehicle_class` varchar(20) NOT NULL,
  `size` varchar(20) NOT NULL,
  `size_label` varchar(255) NOT NULL,
  `model` varchar(255) NOT NULL,
  `blurb` varchar(255) NOT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `image_alt` varchar(255) DEFAULT NULL,
  `sort_order` int unsigned NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `site_vehicles_class_size_unique` (`vehicle_class`,`size`),
  KEY `site_vehicles_is_active_index` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `rate_cards` (
  `id` char(36) NOT NULL,
  `kind` varchar(30) NOT NULL,
  `vehicle_class` varchar(20) DEFAULT NULL,
  `size` varchar(20) DEFAULT NULL,
  `tier` tinyint unsigned NOT NULL,
  `amount_cents` int unsigned NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rate_cards_kind_vehicle_class_size_tier_unique` (`kind`,`vehicle_class`,`size`,`tier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `site_content` (
  `key` varchar(100) NOT NULL,
  `data` json NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

